export function createNestLook(seed) {
  const rng = mulberry32(seed);
  const blobs = [];
  for (let i = 0; i < 18; i++) {
    const a = (i / 18) * TAU + rand(rng, -0.1, 0.1);
    const r = rand(rng, 88, 128);
    blobs.push({
      x: Math.cos(a) * r,
      y: Math.sin(a) * r * 0.72,
      w: rand(rng, 30, 58),
      h: rand(rng, 20, 38),
      rot: rng() * TAU,
      color: pick(rng, ['#8b6a44', '#96754c', '#7d5e3c', '#a07e51']),
    });
  }
  const pebbles = [];
  for (let i = 0; i < 46; i++) {
    const a = rng() * TAU;
    const r = rand(rng, 35, 120);
    pebbles.push({
      x: Math.cos(a) * r,
      y: Math.sin(a) * r * 0.68,
      w: rand(rng, 2, 6),
      h: rand(rng, 1.5, 3.5),
      rot: rng() * TAU,
      tone: pick(rng, ['#b8b09a', '#9b9583', '#d0c6ac', '#857f70']),
    });
  }
  const flowers = [];
  for (let i = 0; i < 16; i++) {
    const a = rng() * TAU;
    const r = rand(rng, 105, 148);
    flowers.push({
      x: Math.cos(a) * r,
      y: Math.sin(a) * r * 0.7,
      s: rand(rng, 0.45, 0.8),
      color: pick(rng, ['#f4edc9', '#e9c95f', '#d9a3c7', '#e59a8f']),
      rot: rng() * TAU,
    });
  }
  const grass = [];
  for (let i = 0; i < 26; i++) {
    const a = rng() * TAU;
    const r = rand(rng, 118, 158);
    grass.push({ x: Math.cos(a) * r, y: Math.sin(a) * r * 0.7, s: rand(rng, 0.4, 0.85), rot: rng() * TAU });
  }
  return { blobs, pebbles, flowers, grass };
}

export function drawNest(ctx, nest, look, time) {
  const { x, y, stage } = nest;
  const t = time;

  // Shadow.
  ctx.fillStyle = 'rgba(24,34,16,.2)';
  ctx.beginPath();
  ctx.ellipse(x + 14, y + 24, 142, 74, 0, 0, TAU);
  ctx.fill();

  // Dirt apron.
  for (const b of look.blobs) {
    ctx.save();
    ctx.translate(x + b.x, y + b.y + 10);
    ctx.rotate(b.rot);
    ctx.fillStyle = rgba(b.color, 0.9);
    ctx.beginPath();
    ctx.ellipse(0, 0, b.w, b.h, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  // Main mound.
  const g = ctx.createRadialGradient(x - 42, y - 48, 8, x, y + 6, 138);
  g.addColorStop(0, '#c09a66');
  g.addColorStop(0.42, '#a37f52');
  g.addColorStop(0.75, '#876643');
  g.addColorStop(1, '#6d5034');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(x, y + 2, 132, 88, 0, 0, TAU);
  ctx.fill();

  // Warm rim light from the upper left.
  ctx.strokeStyle = 'rgba(232,203,148,.35)';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.ellipse(x - 4, y - 2, 120, 78, 0, Math.PI * 0.95, Math.PI * 1.72);
  ctx.stroke();

  // Concentric ridges.
  for (let i = 0; i < 4; i++) {
    const rr = 34 + i * 22;
    ctx.strokeStyle = `rgba(80,56,33,${0.22 - i * 0.03})`;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.ellipse(x + (i % 2 ? 3 : -2), y + 3, rr * 1.15, rr * 0.72, 0, Math.PI * (0.15 + i * 0.1), Math.PI * (1.75 + i * 0.05));
    ctx.stroke();
  }

  // Pebbles and crumbs.
  for (const p of look.pebbles) {
    ctx.save();
    ctx.translate(x + p.x, y + p.y + 6);
    ctx.rotate(p.rot);
    ctx.fillStyle = p.tone;
    ctx.beginPath();
    ctx.ellipse(0, 0, p.w, p.h, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  // Main entrance.
  const hole = ctx.createRadialGradient(x - 3, y + 4, 2, x, y + 10, 30);
  hole.addColorStop(0, '#120a05');
  hole.addColorStop(0.65, '#24150b');
  hole.addColorStop(1, '#4b311c');
  ctx.fillStyle = hole;
  ctx.beginPath();
  ctx.ellipse(x, y + 10, 27, 17, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(206,170,115,.35)';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.ellipse(x, y + 10, 29, 19, 0, Math.PI * 1.05, Math.PI * 1.9);
  ctx.stroke();

  // A few loose crumbs around the mouth.
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU;
    ctx.fillStyle = 'rgba(150,117,74,.8)';
    ctx.beginPath();
    ctx.arc(x + Math.cos(a) * rand(1, 1) * 36, y + 10 + Math.sin(a) * 23, 1.6, 0, TAU);
    ctx.fill();
  }

  // Stage decorations.
  if (stage >= 1) {
    for (const f of look.flowers) {
      ctx.save();
      ctx.translate(x + f.x, y + f.y + 10);
      ctx.rotate(f.rot);
      ctx.fillStyle = f.color;
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * TAU;
        ctx.beginPath();
        ctx.ellipse(Math.cos(a) * 3.2 * f.s, Math.sin(a) * 2.8 * f.s, 2.8 * f.s, 2 * f.s, a, 0, TAU);
        ctx.fill();
      }
      ctx.fillStyle = '#e2b45c';
      ctx.beginPath();
      ctx.arc(0, 0, 1.6 * f.s, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
  }

  if (stage >= 2) {
    // Leaf banner on a twig.
    ctx.strokeStyle = '#6b4a2c';
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(x + 92, y - 14);
    ctx.quadraticCurveTo(x + 100, y - 56, x + 96, y - 86);
    ctx.stroke();
    ctx.save();
    ctx.translate(x + 96, y - 76);
    ctx.rotate(Math.sin(t * 1.2) * 0.08 + 0.2);
    ctx.fillStyle = '#7fa547';
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(20, -10, 34, 8, 10, 24);
    ctx.bezierCurveTo(2, 16, -4, 8, 0, 0);
    ctx.fill();
    ctx.strokeStyle = 'rgba(60,84,32,.5)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(1, 2);
    ctx.lineTo(16, 16);
    ctx.stroke();
    ctx.restore();

    // Secondary entrance.
    ctx.fillStyle = '#2b190d';
    ctx.beginPath();
    ctx.ellipse(x - 72, y + 22, 13, 8, -0.2, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(200,165,110,.28)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.ellipse(x - 72, y + 22, 14, 9, -0.2, 0, TAU);
    ctx.stroke();
  }

  if (stage >= 3) {
    // Little flower arch and glowing spores.
    for (let i = 0; i < 7; i++) {
      const a = Math.PI + (i / 6) * Math.PI;
      const px = x + Math.cos(a) * 44;
      const py = y - 22 + Math.sin(a) * 32;
      ctx.fillStyle = i % 2 ? '#f6efd0' : '#e8c65d';
      ctx.beginPath();
      ctx.arc(px, py, 2.6, 0, TAU);
      ctx.fill();
    }
    for (let i = 0; i < 8; i++) {
      const a = t * 0.4 + (i / 8) * TAU;
      const r = 70 + Math.sin(t * 1.4 + i) * 12;
      ctx.fillStyle = `rgba(255,239,178,${0.2 + Math.sin(t * 2 + i) * 0.12})`;
      ctx.beginPath();
      ctx.arc(x + Math.cos(a) * r, y - 10 + Math.sin(a) * r * 0.55, 1.6, 0, TAU);
      ctx.fill();
    }
  }

  // Tiny grass around the base.
  for (const gr of look.grass) {
    ctx.save();
    ctx.translate(x + gr.x, y + gr.y + 8);
    ctx.rotate(gr.rot);
    ctx.strokeStyle = 'rgba(104,132,64,.7)';
    ctx.lineWidth = 1.2;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(2 * gr.s, -8 * gr.s, (i - 1) * 5 * gr.s, -15 * gr.s);
      ctx.stroke();
    }
    ctx.restore();
  }
}

