content.text:
Now the main game.js. This is the core. Need carefully implement everything.

Let me outline:

```js
import {World, RESOURCES} from './world.js';
import {drawAnt, drawButterfly, drawCargoItem, drawNest, drawSprite, drawTreeShadow} from './art.js';
import {AudioManager} from './audio.js';
import {TAU, clamp, dist, damp, angleLerp, lerp} from './utils.js';

const OBJECTIVES = [...]
const STORAGE_KEY = 'colonia-aurora-v1';
```

Initialize after DOM ready (module at end body, so DOM ready).

Canvas setup:
```
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d', {alpha:false});
let dpr = Math.min(window.devicePixelRatio||1,2);
let viewW=0,viewH=0;
function resize(){ viewW=innerWidth; viewH=innerHeight; canvas.width=Math.round(viewW*dpr); canvas.height=Math.round(viewH*dpr); canvas.style.width=viewW+'px'...; ctx.imageSmoothingEnabled=true; camera.clamp; resizeMinimap?}
```

Game state load:
```
const state = {
 resources:{food:0,leaves:0,stone:0,wood:0},
 gathered:{...},
 cargo:[],
 capacity:4,
 objectives: OBJECTIVES.map(o=>({...o,done:false})),
 nestStage:0,
 time:0,
 startTime: Date.now(),
 totalDelivered:0
}
```
Load localStorage; validate.

World creation maybe takes ~100ms. Show loading? Game starts immediately; could be okay. Generate synchronously before first frame. Add `<body class=loading>`? Not necessary but maybe a subtle loader. Could add `#boot` overlay; skip.

Player ant:
```
const ant = {x:world.nest.x, y:world.nest.y+190, angle:-Math.PI/2, speed:168, vx:0, vy:0, walkPhase:0, moving:false, target:null, job:null, gatherTimer:0, gatherNode:null, depositTimer:0, cargoType:null, bob:0};
```
Starting position near nest (below entrance). Ensure not blocked: resolve.

Camera:
```
const camera={x:ant.x,y:ant.y,zoom: initialZoom, targetZoom:..., follow:true};
```
initial zoom: `viewW<600?1.18: viewW<1000?1.02:1.0`. Actually world scale 3200 wide; on desktop 1440 at zoom 1 shows 1440 width, ant 30px. Fine. On mobile 390 at 1.18 shows 330 width; ant 30px -> 9% width. Good.

Interaction:
```
const keys = new Set();
let joystick={active:false, x:0,y:0, id:null};
```

Helper screenToWorld:
```
function screenToWorld(sx,sy){ return {x:(sx-viewW/2)/camera.zoom+camera.x, y:(sy-viewH/2)/camera.zoom+camera.y}; }
```

Camera clamp:
```
function clampCamera(){
 const halfW=viewW/(2*camera.zoom), halfH=viewH/(2*camera.zoom);
 if (halfW*2>=world.width) camera.x=world.width/2; else camera.x=clamp(camera.x,halfW,world.width-halfW);
 ...
}
```

Follow:
```
const lead = 42; targetX=ant.x+Math.cos(ant.angle)*lead*Math.min(1, speed/100) ...
camera.x=damp(camera.x,targetX,5,dt)
```
When follow false no move. Zoom damp.

Update movement:
```
function updateAnt(dt,time){
 let ix=0, iy=0;
 if keys w/a/s/d or arrows...
 if joystick.active {ix=joystick.x; iy=joystick.y;}
 const manual = Math.hypot(ix,iy)>0.05;
 if (manual) { cancel job; ant.target=null; }
 else if (ant.job) updateJob(dt);
 else if (ant.target) { ... }
 // desired velocity
 let desiredX=0, desiredY=0;
 if manual: normalize; speed = ant.speed * world.speedAt(...) * (joystick magnitude)
 else if moveTarget: direction; speed...
 // acceleration
 ant.vx = damp(ant.vx, desiredX, 10, dt) ...
 // move
 const nx = ant.x + ant.vx*dt; ...
 const resolved = world.resolveCollision(nx,ny,11); ant.x=..., ant.y=...
 // angle
 if speed>8 angle target...
 // walkPhase += speed*dt*0.14
 // footstep timer
}
```
If job handles movement by setting target/arriving:
Simplify: compute `moveTo` each frame:
- If manual: desired vector.
- Else if ant.job: 
  - phase gather: if node amount <=0 -> job=null; else target node; if dist<58 stop and gather (timer).
  - phase return: target nest; if dist<95 deposit and then if node has amount -> phase gather else job=null.
- Else if ant.target: target point; if dist<7 clear.
- Auto deposit when near nest with cargo (any movement mode, except when manual? Should auto deposit even manual). If cargo.length && dist(nest)<105 && depositCooldown<=0 -> deposit. That means walking through nest deposits. Good.
- Gather manual with action; auto job gather timer.

Implement `arrive` threshold 58 for node; for nest 100.

Job:
```
function startJob(node){
 ant.job={node, phase:'gather'};
 ant.target=null;
 toast(`Recolectando ${RESOURCES[node.type].plural}…`, icon)
}
```
Update job:
```
if (!ant.job) return;
const node=ant.job.node;
if (ant.job.phase==='gather'){
 if (node.amount<=0){ ant.job=null; ant.target=null; toast('Ese recurso se agotó. Busca otro.',...); return; }
 if (dist(ant,node)>54) { ant.moveTarget={x:node.x,y:node.y+6}; }
 else { ant.moveTarget=null; gatherTimer -= dt; if <=0 {gather(node); gatherTimer=0.52;} }
} else if (phase==='return'){
 ant.moveTarget={x:nest.x, y:nest.y+90};
 if (dist(ant,nest)<105) { depositAll(); if (node.amount>0 && state.cargo.length<cap) ant.job.phase='gather'; else ant.job=null; }
}
```
But depositAll may be called automatically too. Need avoid double. `depositAll` returns count. Set ant.job.phase after.

Auto deposit:
```
if (state.cargo.length && dist(ant,nest)<108) { depositAll(); }
```
This handles job return and manual. If job exists, after deposit job.phase should be 'gather' if node remains, else null. depositAll can set that.

Gather function:
```
function gather(node){
 if (!node || node.amount<=0)...
 if (state.cargo.length>=state.capacity){ toast('Carga completa...', 'nest'); return false;}
 node.amount--; node.pulse=1;
 state.cargo.push(node.type);
 spawnParticles(...)
 audio.pickup(node.type)
 updateHUD()
 if (node.amount===0){ node.regrow=node.regrowTime; }
 if (state.cargo.length>=cap){ toast('Carga completa. Vuelve al nido.', 'nest'); if (ant.job) ant.job.phase='return'; }
 return true;
}
```
When cargo full, job should switch to return even if node has more. If manual, just toast.

Deposit:
```
function depositAll(){
 if(!state.cargo.length) return 0;
 const summary={};
 for kind: info=RESOURCES[kind]; resources[cat]+=value; gathered[cat]+=value; summary[cat]=(...)+value;
 state.totalDelivered += cargo.length;
 state.cargo=[];
 audio.deposit();
 particles at nest; 
 checkObjectives();
 save();
 updateHUD();
 toast(`Depositado: ...`, 'nest');
 if (ant.job){ if(ant.job.node.amount>0) ant.job.phase='gather'; else ant.job=null; }
 return count;
}
```
Summary string: group categories with amounts: "3 semillas · 1 hoja". Use plural labels. Map category to label.
- food "semillas", leaves "hojas", stone "piedritas", wood "ramitas".

Objectives:
```
function checkObjectives(){
 let newDone=false;
 for obj: if !done && resources[obj.cat]>=obj.target { done=true; state.nestStage=Math.min(3, state.nestStage+1); newDone=true; toast(`Objetivo completado: ${obj.label}`, 'check'); audio.objective(); }
 if all done && !state.celebrated { state.celebrated=true; state.nestStage=3; show banner / confetti; audio.complete(); }
}
```
Note nest stage: 3 objectives => stage 3. If load saved with done objectives, recompute stage.

Objective definitions:
- leaves target 12, icon leaf, category leaves, label "Hojas frescas", short "Hojas".
- food target 15, icon seed, label "Semillas y bayas", short "Semillas".
- stone target 8, icon stone, label "Piedritas", short "Piedras".

World.nest.stage = state.nestStage each frame.

UI functions:
- `buildQuestList()` innerHTML with items; update width.
- `updateQuestUI()`.
- `updateStats(bumpCat)`.
- `renderCargo()`.
- `updateActionButton()`.
- `toast(message, kind)` creates div with icon; max 3; remove after 3.2s with out class.
- intro show after 600ms, hide after 9000; close.
- sound button toggles.
- help modal open/close, build modal quests.
- reset button confirm state.

Action logic:
```
function context(){
 const node=nearestNode(ant.x,ant.y,92);
 const nearNest=dist(ant,nest)<125;
 if (nearNest && cargo.length) return {label:'Depositar', icon:'nest', mode:'deposit', class:'nest'};
 if (node && cargo.length<cap) return {label:'Recolectar', icon:'leaf', mode:'gather', node, class:'ready'};
 if (node && cargo.length>=cap) return {label:'Al nido', icon:'arrow', mode:'return', class:'return'};
 if (cargo.length) return {label:'Al nido', icon:'arrow', mode:'return', class:'return'};
 const any=nearestNode(ant.x,ant.y,900);
 return {label: any?'Buscar':'Explorar', icon:any?'leaf':'ant', mode:any?'job':'explore', node:any, class:''};
}
```
If "explore" and no resources near, find nearest any within world; always some. So "Buscar" mode starts job nearest within 1100. If none, toast.

`performAction()`:
- deposit if near nest & cargo.
- gather nearest node within 95 if cargo space; if full -> start return.
- if cargo -> start return (target nest, job=null).
- else find nearest node within 1200 -> startJob; if none toast.
Action press animation.

`nearestNode(x,y,maxDist)` iterate resources amount>0, choose min. Return null if >max.

Tap:
```
function handleTap(wx,wy){
 const node = nearestNodeToPoint(wx,wy,58);
 if (node) { startJob(node); marker; return; }
 if (dist(wx,wy,nest)<150) { ant.target={x:nest.x,y:nest.y+90}; ant.job=null; if(cargo.length) toast('Volviendo al nido...'); return; }
 ant.job=null; ant.target={x:wx,y:wy}; spawn marker;
}
```
Also if tap on a resource within 70 even if ant far. Resource sprite radius ~45*scale; 65 good.
Marker: {x,y,t:0,type}. Draw pulsing ring and leaf icon? Draw ring.

Manual movement cancels job and target. But if joystick small noise, use threshold .12.

Keyboard:
- keydown: WASD/arrows set; Space/E/Enter performAction; Q or C recenter; +/- zoom; Escape closes modal; H opens help.
- prevent default for arrows/space.

Pointer handling on canvas:
```
const pointers = new Map();
let gesture = {mode:null, startX,...};
canvas.addEventListener('pointerdown', e=>{
 if(e.button!==0 && e.pointerType==='mouse') { maybe right drag; prevent context menu }
 audio.unlock();
 canvas.setPointerCapture(e.pointerId);
 pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,startTime:performance.now(),moved:false});
 if (pointers.size===1){ gesture = {...} } else if (pointers.size===2){ pinchStartDist; pinchStartZoom; }
});
canvas.addEventListener('pointermove', e=>{
 if(!pointers.has(e.pointerId)) return;
 const p=pointers.get(e.pointerId);
 const dx=e.clientX-p.x, dy=e.clientY-p.y;
 p.x=e.clientX; p.y=e.clientY;
 if (pointers.size===1){
   const total = Math.hypot(e.clientX-p.startX, e.clientY-p.startY);
   if (total>10) p.moved=true;
   if (p.moved) {
     camera.follow=false; showRecenter();
     camera.x -= dx/camera.zoom; camera.y -= dy/camera.zoom; clampCamera();
     canvas.classList.add('dragging');
   }
 } else if (pointers.size===2){
   // pinch
   const pts=[...pointers.values()];
   const d=Math.hypot(...);
   if (pinchStartDist) { camera.targetZoom = clamp(pinchStartZoom * d/pinchStartDist, .65, 1.9); }
   // mark moved
 }
});
```
Pinch while pointers move individually; need pinchStart set on second down. Use `pinch = {dist, zoom}`. On move compute. Also allow two-finger pan? skip.

On pointerup:
```
if (pointers.size===1 && !p.moved && performance.now()-p.startTime<500 && !pinchUsed) {
 const wx=...
 handleTap(wx,wy);
}
pointers.delete(id); if(size<2) pinch=null; if(size===0) { gesture=null; canvas.classList.remove('dragging'); }
```
But p.moved threshold 10; taps on mobile okay. When dragging starts, no tap.

Wheel:
```
e.preventDefault(); camera.targetZoom=clamp(camera.targetZoom * (e.deltaY>0?0.9:1.1),0.65,1.9);
```
Maybe zoom toward cursor? Keep center.

Camera zoom buttons update targetZoom. Recenter sets follow=true and target zoom? just follow true; hide button.

Minimap click:
- compute rect; x ratio * world.width; y ratio * world.height; handleTap(worldX, worldY) but for far targets it will walk. Good.
- maybe show ring marker.

Joystick:
```
const base=document.querySelector('.joystick-base');
let joyPointer=null;
base.addEventListener('pointerdown', e=>{
 e.preventDefault(); audio.unlock();
 joyPointer=e.pointerId; base.setPointerCapture; joystick.active=true; base.classList.add('active'); update(e);
});
pointermove... if id matches update.
pointerup/cancel -> reset.
function update(e){ const rect=base.getBoundingClientRect(); cx=..., cy=...; dx=e.clientX-cx...; max=rect.width/2-14; clamp; knob.style.transform=`translate(${dx}px,${dy}px)`; joystick.x=dx/max; joystick.y=dy/max; }
```
