const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const results = [];
function log(name, data) {
  results.push({ name, ...data });
  console.log(name, JSON.stringify(data));
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 390, height: 844 },
    isMobile: true,
    hasTouch: true,
    deviceScaleFactor: 2,
  });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => {
    if (m.type() === 'error' && !m.text().includes('favicon')) errors.push('console: ' + m.text());
  });

  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(1400);

  const client = await context.newCDPSession(page);

  log('init', await page.evaluate(() => ({
    joyDisplay: getComputedStyle(document.querySelector('.joystick')).display,
    isTouchClass: document.body.classList.contains('is-touch'),
    coarse: matchMedia('(pointer: coarse)').matches,
    ant: { x: Math.round(window.coloniaAurora.ant.x), y: Math.round(window.coloniaAurora.ant.y) },
    zoom: +window.coloniaAurora.camera.targetZoom.toFixed(3),
  })));

  // --- joystick drag ---
  const joyBox = await page.locator('.joystick-base').boundingBox();
  const jcx = joyBox.x + joyBox.width / 2;
  const jcy = joyBox.y + joyBox.height / 2;
  const beforeJoy = await page.evaluate(() => ({ x: window.coloniaAurora.ant.x, y: window.coloniaAurora.ant.y }));
  await client.send('Input.dispatchTouchEvent', {
    type: 'touchStart',
    touchPoints: [{ x: jcx, y: jcy, id: 1 }],
  });
  await client.send('Input.dispatchTouchEvent', {
    type: 'touchMove',
    touchPoints: [{ x: jcx + 40, y: jcy, id: 1 }],
  });
  await page.waitForTimeout(900);
  const joyActive = await page.evaluate(() => ({
    active: document.querySelector('.joystick').classList.contains('active'),
    knob: document.querySelector('.joystick-knob').style.transform,
  }));
  await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await page.waitForTimeout(120);
  const afterJoy = await page.evaluate(() => ({
    x: window.coloniaAurora.ant.x,
    y: window.coloniaAurora.ant.y,
    active: document.querySelector('.joystick').classList.contains('active'),
  }));
  log('joystick', {
    movedPx: +Math.hypot(afterJoy.x - beforeJoy.x, afterJoy.y - beforeJoy.y).toFixed(1),
    during: joyActive,
    afterActive: afterJoy.active,
  });

  // --- tap to move on canvas ---
  const camBefore = await page.evaluate(() => ({ follow: window.coloniaAurora.camera.follow, x: window.coloniaAurora.camera.x }));
  await page.touchscreen.tap(300, 560);
  await page.waitForTimeout(250);
  const tapState = await page.evaluate(() => {
    const g = window.coloniaAurora;
    return { target: g.ant.target && { x: Math.round(g.ant.target.x), y: Math.round(g.ant.target.y) }, job: !!g.ant.job };
  });
  log('tap-to-move', { camBefore, tapState });

  // --- minimap tap ---
  const mapBox = await page.locator('#minimap').boundingBox();
  await page.touchscreen.tap(mapBox.x + mapBox.width * 0.7, mapBox.y + mapBox.height * 0.3);
  await page.waitForTimeout(300);
  log('minimap-tap', await page.evaluate(() => {
    const g = window.coloniaAurora;
    return { target: g.ant.target && { x: Math.round(g.ant.target.x), y: Math.round(g.ant.target.y) }, follow: g.camera.follow };
  }));

  // --- pinch zoom ---
  const zoomBefore = await page.evaluate(() => window.coloniaAurora.camera.targetZoom);
  await client.send('Input.dispatchTouchEvent', {
    type: 'touchStart',
    touchPoints: [
      { x: 150, y: 470, id: 11 },
      { x: 240, y: 470, id: 12 },
    ],
  });
  await client.send('Input.dispatchTouchEvent', {
    type: 'touchMove',
    touchPoints: [
      { x: 105, y: 470, id: 11 },
      { x: 285, y: 470, id: 12 },
    ],
  });
  await page.waitForTimeout(120);
  await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await page.waitForTimeout(250);
  log('pinch', {
    before: +zoomBefore.toFixed(3),
    after: +(await page.evaluate(() => window.coloniaAurora.camera.targetZoom)).toFixed(3),
  });

  // --- action button ---
  const actionBefore = await page.evaluate(() => ({
    label: document.querySelector('#action-text').textContent.trim(),
    cargo: window.coloniaAurora.state.cargo.length,
  }));
  const ab = await page.locator('#action-btn').boundingBox();
  await page.touchscreen.tap(ab.x + ab.width / 2, ab.y + ab.height / 2);
  await page.waitForTimeout(400);
  const actionAfter = await page.evaluate(() => ({
    label: document.querySelector('#action-text').textContent.trim(),
    cargo: window.coloniaAurora.state.cargo.length,
    job: window.coloniaAurora.ant.job ? window.coloniaAurora.ant.job.phase : null,
  }));
  log('action', { before: actionBefore, after: actionAfter });

  // --- objective progress UI ---
  await page.evaluate(() => {
    const g = window.coloniaAurora;
    g.state.cargo = ['leaf', 'leaf', 'leaf', 'pebble'];
    g.depositAll();
  });
  await page.waitForTimeout(500);
  log('quest-progress', await page.evaluate(() => ({
    leaves: window.coloniaAurora.state.resources.leaves,
    stone: window.coloniaAurora.state.resources.stone,
    dom: document.querySelector('#quest-list').innerText.replace(/\n/g, ' | '),
    bar: document.querySelector('.quest-item.current .quest-bar i').style.width,
  })));
  await page.screenshot({ path: 'screenshots/mobile-progress.jpg', type: 'jpeg', quality: 88 });

  // --- sound toggle ---
  await page.tap('#btn-sound');
  await page.waitForTimeout(300);
  log('sound', await page.evaluate(() => ({
    muted: document.querySelector('#btn-sound').getAttribute('aria-pressed'),
    stored: localStorage.getItem('colonia-aurora-v1') ? JSON.parse(localStorage.getItem('colonia-aurora-v1')).muted : 'no-save',
  })));

  // --- persistence ---
  await page.evaluate(() => {
    window.coloniaAurora.state.resources.leaves = 7;
    window.coloniaAurora.saveState();
  });
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(1200);
  log('persistence', await page.evaluate(() => ({
    leaves: window.coloniaAurora.state.resources.leaves,
    questDom: document.querySelector('#quest-list').innerText.replace(/\n/g, ' | '),
  })));

  // --- help modal ---
  await page.tap('#btn-help');
  await page.waitForTimeout(350);
  const modalInfo = await page.evaluate(() => {
    const m = document.querySelector('#modal');
    const card = m.querySelector('.modal-card');
    return {
      hidden: m.hidden,
      cardH: card.scrollHeight,
      visibleH: card.clientHeight,
      scrollable: card.scrollHeight > card.clientHeight,
      resetLabel: document.querySelector('#btn-reset').textContent.trim(),
    };
  });
  log('modal', modalInfo);
  await page.screenshot({ path: 'screenshots/mobile-help.jpg', type: 'jpeg', quality: 85 });
  await page.tap('#btn-reset');
  await page.waitForTimeout(250);
  log('reset-armed', await page.evaluate(() => ({
    label: document.querySelector('#btn-reset').textContent.trim(),
    confirm: document.querySelector('#btn-reset').classList.contains('confirm'),
  })));
  // disarm by waiting / close instead of resetting progress here
  await page.tap('#modal-close');

  // --- landscape ---
  await page.setViewportSize({ width: 844, height: 390 });
  await page.waitForTimeout(700);
  log('landscape', await page.evaluate(() => ({
    joy: getComputedStyle(document.querySelector('.joystick')).display,
    quest: document.querySelector('.quest-card').getBoundingClientRect().toJSON(),
    map: document.querySelector('.map-cluster').getBoundingClientRect().toJSON(),
    cargo: document.querySelector('.cargo').getBoundingClientRect().toJSON(),
    action: document.querySelector('#action-btn').getBoundingClientRect().toJSON(),
    introShown: document.querySelector('#intro').classList.contains('show'),
  })));
  await page.screenshot({ path: 'screenshots/landscape-1.jpg', type: 'jpeg', quality: 88 });

  log('errors', { errors });
  await browser.close();
})().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});

