const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 390, height: 844 },
    isMobile: true,
    hasTouch: true,
    deviceScaleFactor: 2,
  });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => {
    if (m.type() === 'error' && !m.text().includes('favicon')) errors.push('console: ' + m.text());
  });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.evaluate(() => { localStorage.clear(); });
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(1300);

  // find an empty patch of grass near the ant
  const spot = await page.evaluate(() => {
    const g = window.coloniaAurora;
    const { ant, camera, world } = g;
    for (let ring = 90; ring <= 260; ring += 30) {
      for (let a = 0; a < 12; a++) {
        const ang = (a / 12) * Math.PI * 2;
        const wx = ant.x + Math.cos(ang) * ring;
        const wy = ant.y + Math.sin(ang) * ring;
        if (world.isBlocked(wx, wy, 16)) continue;
        if (world.resources.some((r) => Math.hypot(r.x - wx, r.y - wy) < 80)) continue;
        if (Math.hypot(world.nest.x - wx, world.nest.y - wy) < 160) continue;
        return {
          wx, wy,
          sx: (wx - camera.x) * camera.zoom + innerWidth / 2,
          sy: (wy - camera.y) * camera.zoom + innerHeight / 2,
        };
      }
    }
    return null;
  });
  console.log('spot', spot);
  if (spot) {
    await page.touchscreen.tap(spot.sx, spot.sy);
    await page.waitForTimeout(300);
    console.log('tap-move', await page.evaluate((s) => {
      const g = window.coloniaAurora;
      return {
        job: !!g.ant.job,
        target: g.ant.target && { x: Math.round(g.ant.target.x), y: Math.round(g.ant.target.y) },
        expected: { x: Math.round(s.wx), y: Math.round(s.wy) },
      };
    }, spot));
  }

  // sound toggle + persistence of mute
  const soundBefore = await page.getAttribute('#btn-sound', 'aria-pressed');
  await page.tap('#btn-sound');
  await page.waitForTimeout(250);
  const soundAfter = await page.evaluate(() => ({
    pressed: document.querySelector('#btn-sound').getAttribute('aria-pressed'),
    label: document.querySelector('#btn-sound').getAttribute('aria-label'),
    stored: localStorage.getItem('colonia-aurora-muted'),
  }));
  console.log('sound', { before: soundBefore, after: soundAfter });
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(900);
  console.log('sound-persisted', await page.getAttribute('#btn-sound', 'aria-pressed'));

  // reset flow
  await page.tap('#btn-help');
  await page.waitForTimeout(300);
  await page.locator('.modal-card').evaluate((el) => { el.scrollTop = el.scrollHeight; });
  await page.tap('#btn-reset');
  await page.waitForTimeout(200);
  await Promise.all([
    page.waitForLoadState('load'),
    page.tap('#btn-reset'),
  ]);
  await page.waitForTimeout(1300);
  console.log('after-reset', await page.evaluate(() => ({
    leaves: window.coloniaAurora.state.resources.leaves,
    total: window.coloniaAurora.state.totalDelivered,
    stage: window.coloniaAurora.state.nestStage,
    modalHidden: document.querySelector('#modal').hidden,
  })));
  console.log('errors', errors);
  await browser.close();
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

